<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>选项卡片</title>

    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&family=Caveat:wght@400..700&display=swap" rel="stylesheet">

<style>
:root {
    --accent-color: #6dd5d5;
    --text-primary: #d4d0c8;
    --border-color: #2a2a2a;
    --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.6);
    --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* { box-sizing: border-box; }

body {
    margin: 0;
    padding: 12px;
    font-family: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    background: transparent;
    color: var(--text-primary);
    display: flex;
    justify-content: center;
}

.choice-card {
    width: 100%;
    max-width: 380px;
    background: linear-gradient(135deg, #1a1a1a 0%, #0f0f0f 100%);
    border-radius: 12px;
    padding: 20px;
    box-shadow: var(--shadow-md), inset 0 1px 0 rgba(255,255,255,0.05);
    border: 1px solid var(--border-color);
}

/* 优化了头部布局，采用 space-between 两端对齐，避免移动端挤压 */
.card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
    cursor: pointer;
    user-select: none;
    width: 100%;
}

.header-center-group {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    flex: 1; /* 让中央区域占据剩余空间 */
    text-align: center;
}

.header-title {
    font-family: 'Caveat', cursive;
    font-size: 26px;
    font-weight: 700;
    letter-spacing: 2px;
    background: linear-gradient(135deg, #6dd5d5 0%, #88d8b0 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    white-space: nowrap;
}

.header-icon {
    font-size: 20px;
    filter: drop-shadow(0 0 8px rgba(109,213,213,0.4));
    transition: transform var(--transition);
}

.card-header:hover .header-icon {
    transform: scale(1.15) rotate(10deg);
}

.mode-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 3px 10px;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    background: transparent;
    color: #555;
    font-family: 'Noto Sans SC', sans-serif;
    font-size: 11px;
    cursor: pointer;
    transition: all var(--transition);
    white-space: nowrap;
    line-height: 1.4;
    flex-shrink: 0; /* 保证按钮不会被压缩变形 */
}

.mode-btn:hover {
    border-color: #555;
    color: #999;
}

.mode-btn.active {
    border-color: var(--accent-color);
    color: var(--accent-color);
    background: rgba(109,213,213,0.1);
    box-shadow: 0 0 8px rgba(109,213,213,0.2);
}

.options-container {
    display: grid;
    grid-template-rows: 1fr;
    transition: grid-template-rows var(--transition);
    overflow: hidden;
}

.options-container.collapsed {
    grid-template-rows: 0fr;
}

.options-wrapper {
    overflow: hidden;
    min-height: 0;
}

.options-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    list-style: none;
    margin: 0;
    padding: 0;
}

.option-item {
    position: relative;
    padding: 14px 16px;
    background: linear-gradient(135deg, #1a1a1a 0%, #151515 100%);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    cursor: pointer;
    font-size: 14px;
    color: var(--text-primary);
    transition: all var(--transition);
    overflow: hidden;
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.option-item::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 3px; height: 100%;
    background: linear-gradient(180deg, var(--accent-color) 0%, #5dd5d5 100%);
    transform: scaleY(0);
    transform-origin: top;
    transition: transform var(--transition);
    box-shadow: 0 0 8px rgba(109,213,213,0.5);
}

.option-item::after {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: radial-gradient(circle at var(--mouse-x, 50%) var(--mouse-y, 50%), rgba(109,213,213,0.1) 0%, transparent 80%);
    opacity: 0;
    transition: opacity var(--transition);
    pointer-events: none;
}

.option-item:hover {
    background: linear-gradient(135deg, #1f2a2a 0%, #1a2525 100%);
    border-color: var(--accent-color);
    color: var(--accent-color);
    box-shadow: 0 0 16px rgba(109,213,213,0.3), inset 0 0 16px rgba(109,213,213,0.05);
    transform: translateX(4px);
}

.option-item:hover::before { transform: scaleY(1); }
.option-item:hover::after  { opacity: 1; }
.option-item:active { transform: translateX(4px) scale(0.98); }

.option-label {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 22px; width: 22px; height: 22px;
    background: linear-gradient(135deg, var(--accent-color) 0%, #5dd5d5 100%);
    border-radius: 4px;
    font-size: 11px;
    font-weight: 700;
    flex-shrink: 0;
    color: #0f0f0f;
    box-shadow: 0 0 8px rgba(109,213,213,0.4);
    margin-top: 1px;
}

.option-title {
    font-weight: 500;
    color: var(--accent-color);
    margin-right: 6px;
    white-space: nowrap;
}

.option-content {
    flex: 1;
    line-height: 1.5;
    position: relative;
    z-index: 1;
}

@media (max-width: 600px) {
    body { padding: 8px; }
    .choice-card { padding: 16px; border-radius: 10px; max-width: 100%; }
    .header-title { font-size: 20px; letter-spacing: 1px; } /* 移动端字号微调 */
    .header-icon { font-size: 16px; }
    .option-item { padding: 12px 14px; font-size: 13px; }
    .options-list { gap: 8px; }
    .mode-btn { font-size: 10px; padding: 2px 6px; }
    .header-center-group { gap: 4px; }
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-6px); }
    to   { opacity: 1; transform: translateY(0); }
}

.option-item:nth-child(1) { animation: fadeIn 0.3s ease-out 0.05s both; }
.option-item:nth-child(2) { animation: fadeIn 0.3s ease-out 0.10s both; }
.option-item:nth-child(3) { animation: fadeIn 0.3s ease-out 0.15s both; }
.option-item:nth-child(4) { animation: fadeIn 0.3s ease-out 0.20s both; }
.option-item:nth-child(5) { animation: fadeIn 0.3s ease-out 0.25s both; }
.option-item:nth-child(n+6) { animation: fadeIn 0.3s ease-out 0.30s both; }
</style>
</head>
